class UserNotFoundException extends RuntimeException { UserNotFoundException(int id) { super("Brak uzytkownika id=" + id); } }
static void softDeleteOrThrow(Connection conn, int id) throws SQLException {
  int rows = softDeleteById(conn, id);
  if (rows == 0) throw new UserNotFoundException(id);
}

static void hardDeleteOrThrow(Connection conn, int id) throws SQLException {
  int rows = hardDeleteById(conn, id);
  if (rows == 0) throw new UserNotFoundException(id);
}

static void softDeleteWithAudit(Connection conn, int id) throws SQLException {
  softDeleteById(conn, id);
  try (PreparedStatement audit = conn.prepareStatement("INSERT INTO audit_log (message) VALUES (?)")) {
    audit.setString(1, "Uzytkownik id=" + id + " zdezaktywowany"); audit.executeUpdate();
  }
}

