  hardDeleteById(conn, userId);
}

static void smartDelete(Connection conn, int userId) throws SQLException {
  int orderCount;
  try (PreparedStatement ps = conn.prepareStatement("SELECT COUNT(*) FROM orders WHERE user_id=?")) {
    ps.setInt(1, userId);
    try (ResultSet rs = ps.executeQuery()) { rs.next(); orderCount = rs.getInt(1); }
  }
  if (orderCount > 0) softDeleteById(conn, userId); else hardDeleteById(conn, userId);
}

